INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt0017925','The General',1926,'Action, Adventure, Comedy, Drama, War','1926-tt0017925.webp','https://www.imdb.com/title/tt0017925','https://image.tmdb.org/t/p/w1280//bVABKsniQzkqXa2MjcjUGSFsTL9.jpg','','','{"releaseYear":1926,"deck":"year-1926","metadataSource":"TMDB poster via image search","selection":"public-domain classic wired for streaming (INGEST section 8); catalog row added so the feature presentation resolves its real poster"}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url <> '' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,attributes_json=excluded.attributes_json,updated_at=excluded.updated_at;
